use "./sim.ts" { makeBall, step, draw }

page Home "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref box
  ref ctx
  ref balls
  ref raf

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(makeBall())
    }
    balls = list
    count = balls.length
    frames = 0
    if ctx {
      draw(ctx, balls)
    }
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    if paused && ctx {
      draw(ctx, balls)
    }
  }

  fn tick() {
    step(balls)
    draw(ctx, balls)
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn toggle() {
    if paused {
      paused = false
      raf = requestAnimationFrame(tick)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  mount {
    ctx = box.getContext("2d")
    reset()
    raf = requestAnimationFrame(tick)
    cleanup {
      cancelAnimationFrame(raf)
    }
  }

  column gap=3 pad=4 align=center {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

