export const W = 400;
export const H = 300;
export const R = 10;
const G = 0.2;

export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
}

function rand(a: number, b: number): number {
  return a + Math.random() * (b - a);
}

export function makeBall(): Ball {
  return {
    x: rand(R, W - R),
    y: rand(R, H - R),
    vx: rand(-3, 3),
    vy: rand(-3, 3),
    color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)`,
  };
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += G;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < R) {
      b.x = R;
      b.vx = Math.abs(b.vx);
    } else if (b.x > W - R) {
      b.x = W - R;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y < R) {
      b.y = R;
      b.vy = Math.abs(b.vy);
    } else if (b.y > H - R) {
      b.y = H - R;
      b.vy = -Math.abs(b.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const d2 = dx * dx + dy * dy;
      if (d2 < 4 * R * R) {
        const d = Math.sqrt(d2) || 0.0001;
        const nx = dx / d;
        const ny = dy / d;
        const approaching = (b.vx - a.vx) * dx + (b.vy - a.vy) * dy < 0;
        if (approaching) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
        const overlap = (2 * R - d) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        for (const p of [a, b]) {
          p.x = Math.min(W - R, Math.max(R, p.x));
          p.y = Math.min(H - R, Math.max(R, p.y));
        }
      }
    }
  }
}

export function draw(ctx: CanvasRenderingContext2D, balls: Ball[]): void {
  ctx.clearRect(0, 0, W, H);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

export const W = 400;
export const H = 300;
export const R = 10;
export const GRAVITY = 0.2;

export interface Ball {
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
}

const COLORS = ["#e11d48", "#2563eb", "#16a34a", "#f59e0b", "#9333ea", "#0891b2", "#db2777"];

export function makeBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() * 2 - 1) * 4,
    vy: (Math.random() * 2 - 1) * 4,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

export function makeBalls(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(makeBall());
  return balls;
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;

    if (b.x < R) {
      b.x = R;
      b.vx = Math.abs(b.vx);
    } else if (b.x > W - R) {
      b.x = W - R;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y < R) {
      b.y = R;
      b.vy = Math.abs(b.vy);
    } else if (b.y > H - R) {
      b.y = H - R;
      b.vy = -Math.abs(b.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 2 * R) {
        // intercambio de velocidades (colisión elástica de masas iguales)
        const tvx = a.vx;
        const tvy = a.vy;
        a.vx = b.vx;
        a.vy = b.vy;
        b.vx = tvx;
        b.vy = tvy;

        // separar para que no queden superpuestas
        const nx = dist === 0 ? 1 : dx / dist;
        const ny = dist === 0 ? 0 : dy / dist;
        const overlap = (2 * R - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
      }
    }
  }

  // asegurar que ninguna pelota salga del canvas tras separar
  for (const b of balls) {
    b.x = Math.min(W - R, Math.max(R, b.x));
    b.y = Math.min(H - R, Math.max(R, b.y));
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]): void {
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, W, H);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
  }
}

