use "./sim.ts" { makeBall, makeBalls, step, draw }

page Sim "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref box
  ref balls
  ref raf

  fn reset() {
    balls = makeBalls(5)
    count = balls.length
    frames = 0
    if box {
      draw(box, balls)
    }
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
  }

  fn togglePause() {
    paused = !paused
  }

  fn tick() {
    if !paused {
      step(balls)
      draw(box, balls)
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  mount {
    reset()
    raf = requestAnimationFrame(tick)
    cleanup {
      cancelAnimationFrame(raf)
    }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

// ─── Modelo ───────────────────────────────────────────────

model Viajero {
  id: Number
  nombre: String
  pais: String
  ciudad: String
  llegada: String
  presupuesto: Number
}

// ─── Datos de ejemplo ─────────────────────────────────────

const VIAJEROS = [
  { id: 1, nombre: "Ana Rojas", pais: "Perú", ciudad: "Lima", llegada: "2026-03-12", presupuesto: 1200 },
  { id: 2, nombre: "Bruno Díaz", pais: "México", ciudad: "Oaxaca", llegada: "2026-01-05", presupuesto: 850 },
  { id: 3, nombre: "Carla Gómez", pais: "Perú", ciudad: "Cusco", llegada: "2026-02-20", presupuesto: 2300 },
  { id: 4, nombre: "Diego Silva", pais: "Chile", ciudad: "Valparaíso", llegada: "2026-04-02", presupuesto: 640 },
  { id: 5, nombre: "Elena Ruiz", pais: "México", ciudad: "Mérida", llegada: "2026-03-01", presupuesto: 1500 },
  { id: 6, nombre: "Facundo Paz", pais: "Argentina", ciudad: "Salta", llegada: "2026-02-11", presupuesto: 990 },
  { id: 7, nombre: "Gabriela Luna", pais: "Chile", ciudad: "Santiago", llegada: "2026-01-28", presupuesto: 1750 },
  { id: 8, nombre: "Hugo Vera", pais: "Argentina", ciudad: "Mendoza", llegada: "2026-03-30", presupuesto: 1100 }
]

const PAISES = ["Todos", "Argentina", "Chile", "México", "Perú"]

// ─── Utilidades de formato ────────────────────────────────

fn formatoFecha(iso) {
  let [anio, mes, dia] = iso.split("-")
  return `${dia}/${mes}/${anio}`
}

fn formatoUSD(n) {
  let entero = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
  return `US$ ${entero}`
}

fn iniciales(nombre) {
  return nombre
    .split(" ")
    .filter(p => p.length > 0)
    .map(p => p[0].toUpperCase())
    .join("")
    .slice(0, 2)
}

fn colorDeNombre(nombre) {
  let hash = 0
  for (let i = 0; i < nombre.length; i++) {
    hash = (hash * 31 + nombre.charCodeAt(i)) >>> 0
  }
  return `hsl(${hash % 360}, 60%, 45%)`
}

fn buscarViajero(id) {
  return VIAJEROS.find(v => v.id == Number(id))
}

// ─── Componentes ──────────────────────────────────────────

component Avatar(nombre: String) {
  row align=center justify=center class="avatar" style=(`background: ${colorDeNombre(nombre)}`) {
    text iniciales(nombre) bold
  }

  style {
    .avatar {
      width: 44px;
      height: 44px;
      min-width: 44px;
      border-radius: 50%;
      color: #fff;
    }
  }
}

component TarjetaViajero(v: Viajero) {
  card pad=3 {
    row gap=3 align=center {
      Avatar nombre=v.nombre
      column gap=1 {
        link v.nombre to=(`/viajero/${v.id}`)
        text `${v.ciudad}, ${v.pais}` muted
        text `Llega el ${formatoFecha(v.llegada)}` small
      }
      text formatoUSD(v.presupuesto) bold
    }
  }
}

// ─── Páginas ──────────────────────────────────────────────

page Inicio "/" {
  meta title="Viajeros"

  state pais = "Todos"
  computed lista = VIAJEROS
    .filter(v => pais == "Todos" || v.pais == pais)
    .sort((a, b) => a.llegada.localeCompare(b.llegada))

  column gap=4 pad=4 {
    title "Viajeros" tag=h1
    text `${lista.length} viajeros` muted
    select pais options=PAISES label="País"
    column gap=2 {
      for v in lista key v.id {
        TarjetaViajero v=v
      }
    }
  }
}

page DetalleViajero "/viajero/:id" {
  computed viajero = buscarViajero(params.id)

  column gap=3 pad=4 {
    if viajero {
      row gap=3 align=center {
        Avatar nombre=viajero.nombre
        title viajero.nombre tag=h1
      }
      text `${viajero.ciudad}, ${viajero.pais}`
      text `Llega el ${formatoFecha(viajero.llegada)}`
      text `Presupuesto: ${formatoUSD(viajero.presupuesto)}`
    } else {
      text "Viajero no encontrado" danger
    }
    link "Volver" to="/"
  }
}

// ─── Tests ────────────────────────────────────────────────

test "lista todos los viajeros" {
  open "/"
  see "Viajeros"
  see "8 viajeros"
  see "US$ 1.200"
  see "Llega el 05/01/2026"
}

test "filtra por país" {
  open "/"
  select 0 "Perú"
  see "2 viajeros"
  see "Ana Rojas"
  notSee "Hugo Vera"
}

test "muestra el detalle" {
  open "/"
  link "Carla Gómez"
  see "Cusco, Perú"
  see "Llega el 20/02/2026"
  see "Presupuesto: US$ 2.300"
  link "Volver"
  see "8 viajeros"
}

const TRAVELERS = [
  { id: 1, name: "Ana Rojas", country: "Perú", city: "Lima", arrival: "2026-03-12", budget: 1200 },
  { id: 2, name: "Bruno Díaz", country: "México", city: "Oaxaca", arrival: "2026-01-05", budget: 850 },
  { id: 3, name: "Carla Gómez", country: "Perú", city: "Cusco", arrival: "2026-02-20", budget: 2300 },
  { id: 4, name: "Diego Silva", country: "Chile", city: "Valparaíso", arrival: "2026-04-02", budget: 640 },
  { id: 5, name: "Elena Ruiz", country: "México", city: "Mérida", arrival: "2026-03-01", budget: 1500 },
  { id: 6, name: "Facundo Paz", country: "Argentina", city: "Salta", arrival: "2026-02-11", budget: 990 },
  { id: 7, name: "Gabriela Luna", country: "Chile", city: "Santiago", arrival: "2026-01-28", budget: 1750 },
  { id: 8, name: "Hugo Vera", country: "Argentina", city: "Mendoza", arrival: "2026-03-30", budget: 1100 }
]

const COUNTRIES = ["Todos", "Argentina", "Chile", "México", "Perú"]

fn formatDate(iso) {
  let [y, m, d] = iso.split("-")
  return `${d}/${m}/${y}`
}

fn formatUSD(n) {
  let digits = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
  return `US$ ${digits}`
}

fn initials(name) {
  return name.split(" ").filter(p => p.length > 0).map(p => p[0].toUpperCase()).slice(0, 2).join("")
}

fn hue(name) {
  let h = 0
  for (let i = 0; i < name.length; i++) {
    h = (h * 31 + name.charCodeAt(i)) >>> 0
  }
  return h % 360
}

fn avatarStyle(name) {
  return `background: hsl(${hue(name)}, 60%, 42%)`
}

component Avatar(name: String) {
  style {
    .avatar {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      color: #fff;
      font-weight: 700;
      flex-shrink: 0;
    }
  }

  text initials(name) class="avatar" style=(avatarStyle(name))
}

page Home "/" {
  meta title="Viajeros"

  state country = "Todos"

  computed visible = TRAVELERS
    .filter(t => country == "Todos" || t.country == country)
    .slice()
    .sort((a, b) => a.arrival.localeCompare(b.arrival))

  column gap=4 pad=6 {
    title "Viajeros" tag=h1
    text `${visible.length} viajeros` muted
    select country options=COUNTRIES label="País"
    for t in visible key t.id {
      card {
        row gap=3 align=center {
          Avatar name=t.name
          column gap=1 {
            link t.name to=(`/viajero/${t.id}`)
            text `${t.city}, ${t.country}`
            text `Llega el ${formatDate(t.arrival)}` small muted
            text formatUSD(t.budget) bold
          }
        }
      }
    }
  }
}

page TravelerDetail "/viajero/:id" {
  computed traveler = TRAVELERS.find(t => String(t.id) == params.id)

  column gap=3 pad=6 {
    if traveler {
      row gap=3 align=center {
        Avatar name=traveler.name
        title traveler.name tag=h1
      }
      text `${traveler.city}, ${traveler.country}`
      text `Llega el ${formatDate(traveler.arrival)}`
      text `Presupuesto: ${formatUSD(traveler.budget)}`
    } else {
      title "Viajero no encontrado" tag=h1
    }
    link "Volver" to="/"
  }
}

test "lista y filtra viajeros" {
  open "/"
  see "Viajeros"
  see "8 viajeros"
  see "US$ 1.200"
  see "Llega el 12/03/2026"
  select 0 "Perú"
  see "2 viajeros"
  notSee "Hugo Vera"
}

test "detalle de viajero" {
  open "/viajero/1"
  see "Ana Rojas"
  see "Lima, Perú"
  see "Presupuesto: US$ 1.200"
  link "Volver"
  see "8 viajeros"
}
